import type { CustomBlockErrorInfo } from "@notionhq/custom-blocks-protocol/errors.js"
import {
	type CustomBlockManifest,
	manifestSchema,
} from "@notionhq/custom-blocks-protocol/manifest.js"
import * as v from "valibot"

const MANIFEST_URL = "manifest"

type CustomBlockConnectErrorCode =
	| "manifest_unavailable"
	| "manifest_invalid"
	| (string & {})

type CustomBlockConnectError = CustomBlockErrorInfo<CustomBlockConnectErrorCode>

export type ManifestLoadResult =
	| {
			manifest: CustomBlockManifest | null
			error?: undefined
	  }
	| {
			manifest: null
			error: CustomBlockConnectError
	  }

/**
 * On the literal `localhost` hostname, attempts to load the custom block's optional self-hosted
 * manifest exposed by the worker dev shell, requested at the page-relative `manifest` path so
 * blocks served from a subpath resolve it against their own base.
 *
 * It is up to the host to decide whether to use this manifest or provide its own persisted manifest.
 */
export async function attemptToLoadSelfHostedManifest(
	hostname: string | undefined = typeof window === "undefined"
		? undefined
		: window.location.hostname,
): Promise<ManifestLoadResult> {
	// Runtime manifests are a localhost-only development fallback. Deployed
	// blocks receive their authoritative manifest from the host during init.
	if (hostname !== "localhost") {
		return { manifest: null }
	}

	let response: Response
	try {
		response = await fetch(MANIFEST_URL, { credentials: "omit" })
	} catch (error) {
		const message = `Could not fetch ${MANIFEST_URL}.`
		console.warn(`[custom-blocks-sdk] ${message}`, error)
		return {
			manifest: null,
			// Consider this retryable because it may have just been a network issue. Because `init`
			// errors are considered terminal, the host should "retry" by reloading the iframe and
			// sending another `connect` message.
			error: { code: "manifest_unavailable", message, isRetryable: true },
		}
	}
	if (response.status === 404) {
		const message = `No manifest found at ${MANIFEST_URL} (status ${response.status}).`
		console.warn(`[custom-blocks-sdk] ${message}`)
		return { manifest: null }
	}
	if (!response.ok) {
		const message = `Could not fetch ${MANIFEST_URL} (status ${response.status}).`
		console.warn(`[custom-blocks-sdk] ${message}`)
		return {
			manifest: null,
			error: {
				code: "manifest_unavailable",
				message,
				isRetryable: isRetryableManifestHttpStatus(response.status),
			},
		}
	}

	let json: unknown
	try {
		json = await response.json()
	} catch (error) {
		const message = `Manifest at ${MANIFEST_URL} was not valid JSON.`
		console.warn(`[custom-blocks-sdk] ${message}`, error)
		return {
			manifest: null,
			// Consider invalid manifests as unrecoverable errors.
			error: { code: "manifest_invalid", message, isRetryable: false },
		}
	}

	const parsed = v.safeParse(manifestSchema, json)
	if (!parsed.success) {
		const message = `Manifest at ${MANIFEST_URL} did not match schema.`
		console.warn(`[custom-blocks-sdk] ${message}`, parsed.issues)
		return {
			manifest: null,
			// Consider invalid manifests as unrecoverable errors.
			error: { code: "manifest_invalid", message, isRetryable: false },
		}
	}

	return { manifest: parsed.output }
}

function isRetryableManifestHttpStatus(status: number): boolean {
	// Consider these statuses retryable because they may reflect transient failures.
	return (
		status === 408 || // Request Timeout
		status === 425 || // Too Early
		status === 500 || // Internal Server Error
		status === 502 || // Bad Gateway
		status === 503 || // Service Unavailable
		status === 504 // Gateway Timeout
	)
}
